args.command:
cd /tmp/kvprobe
cat > t3.toml <<'EOF'
[key_value_pairs]
key = { fg = "red", bold = true }
separator = { fg = "green", italic = true }
value = { fg = "blue", underline = true }
EOF
printf 'key=value\n' | /workspace/executable --config-path /tmp/kvprobe/t3.toml --enable key-value-pairs --disable-builtin-keywords | cat -v; echo "EXIT=$?"
cat > t4.toml <<'EOF'
[key_value_pairs]
key = { fg = "red", bg = "blue", faint = true, underline = true, strikethrough = true }
EOF
printf 'key=value\n' | /workspace/executable --config-path /tmp/kvprobe/t4.toml --enable key-value-pairs --disable-builtin-keywords | cat -v; echo "EXIT=$?"
